import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/conversation_model.dart';
import '../models/message_model.dart';
class ChatRepository { ChatRepository(this._db); final FirebaseFirestore _db; Stream<List<ConversationModel>> conversations(String userId)=>_db.collection('conversations').where('participantIds',arrayContains:userId).orderBy('lastMessageAt',descending:true).snapshots().map((s)=>s.docs.map(ConversationModel.fromFirestore).toList()); Stream<List<MessageModel>> messages(String id)=>_db.collection('conversations').doc(id).collection('messages').orderBy('createdAt').snapshots().map((s)=>s.docs.map(MessageModel.fromFirestore).toList()); Future<void> send(String conversationId,MessageModel message) async { final batch=_db.batch(); final conversation=_db.collection('conversations').doc(conversationId); batch.set(conversation.collection('messages').doc(message.id),message.toFirestore()); batch.update(conversation,{'lastMessage':message.text ?? 'مرفق','lastMessageAt':Timestamp.fromDate(message.createdAt),'typingUserIds':FieldValue.arrayRemove([message.senderId])}); await batch.commit(); } Future<void> setTyping(String conversationId,String userId,bool isTyping)=>_db.collection('conversations').doc(conversationId).update({'typingUserIds':isTyping?FieldValue.arrayUnion([userId]):FieldValue.arrayRemove([userId])}); Future<void> react(String conversationId,String messageId,String userId,String emoji)=>_db.collection('conversations').doc(conversationId).collection('messages').doc(messageId).collection('reactions').doc(userId).set({'userId':userId,'emoji':emoji,'createdAt':FieldValue.serverTimestamp()}); }
